package rtmp

import (
	"bytes"
	"context"
	"encoding/hex"
	"github.com/GregoryGost/gost-restreamer/internal/core"
	"github.com/GregoryGost/gost-restreamer/internal/media"
	"github.com/GregoryGost/gost-restreamer/internal/media/codec"
	"github.com/bluenviron/gortmplib/pkg/bytecounter"
	"github.com/bluenviron/gortmplib/pkg/message"
	"testing"
)

// TestSDRNativeRTMPHeadersAndPackets проводит реальные профили CPU-кодировщиков FFmpeg7.1.5
// через штатный исходящий тракт и существующий читатель SDK. Исходные avcC/av1C и AU не перемаршаливаются;
// VideoExSequenceStart обязан отражать настоящие профиль, глубину и субдискретизацию, включая монохромный AV1.
func TestSDRNativeRTMPHeadersAndPackets(t *testing.T) {
	// fixture содержит неизменённые конфигурацию и полный независимый AU выбранного профиля.
	for _, fixture := range []struct {
		// name задаёт реальный профиль и формат пикселей эталона.
		name string
		// videoCodec указывает сжатый видеокодек.
		videoCodec core.Codec
		// headers и au содержат исходные байты кодировщика в hex.
		headers, au string
	}{
		{"av1/main/yuv420p", core.CodecAV1, "81000c000a0d0000000337ffe6d7cc82020202", "0a0d0000000337ffe6d7cc8202020232191000836000008000000000ebc8e585f1278f4eb7b6107d6580"},
		{"av1/main/yuv420p10le", core.CodecAV1, "81004c000a0d0000000337ffe6d7ce82020202", "0a0d0000000337ffe6d7ce8202020232191000846000008000000000ebc8e585f1278f4eb7b601cce580"},
		{"av1/main/gray", core.CodecAV1, "81001c000a0d0000000337ffe6d7cd82020210", "0a0d0000000337ffe6d7cd82020210320e1000836000020000015600a37710"},
		{"av1/high/yuv444p", core.CodecAV1, "812000000a0d2000000337ffe6d7cd04040410", "0a0d2000000337ffe6d7cd0404041032191000836000008000000000ebc8e581d5ccf27df805dea09cb7"},
		{"av1/high/yuv444p10le", core.CodecAV1, "812040000a0d2000000337ffe6d7cf04040410", "0a0d2000000337ffe6d7cf0404041032191000846000008000000000ebc8e581d5ccf27df805de8f9bb7"},
		{"av1/professional/yuv422p", core.CodecAV1, "814008000a0d4000000337ffe6d7cc82020208", "0a0d4000000337ffe6d7cc8202020832191000836000008000000000ebc8e581d5ccf259c1b8ef2afc7c"},
		{"av1/professional/yuv422p10le", core.CodecAV1, "814048000a0d4000000337ffe6d7ce41010104", "0a0d4000000337ffe6d7ce4101010432191000846000008000000000ebc8e581d5ccf259c1b8eef2ba7c"},
		{"h264/baseline/yuv420p", core.CodecH264, "0142c00bffe1001a6742c00bda0811b016a0808088000003000800000301e078a15501000568ce0b2c80", ""},
		{"h264/main/yuv420p", core.CodecH264, "014d400bffe1001a674d400bda0811b016a0808088000003000800000301e078a15501000568ef0b2c80", ""},
		{"h264/high/yuv420p", core.CodecH264, "0164000bffe1001b6764000bacb41023602d41010110000003001000000303c0f142aa01000568ef0b2c8bfdf8f800", ""},
		{"h264/high10/yuv420p10le", core.CodecH264, "016e000bffe1001c676e000ba6cb41023602d41010110000030001000003003c0f142aa001000568ef0b2c8bfdfafa00", ""},
		{"h264/high422/yuv422p", core.CodecH264, "017a000bffe1001b677a000bbcb41023602d41010110000003001000000303c0f142aa01000568ef0b2c8bfef8f800", ""},
		{"h264/high422/yuv422p10le", core.CodecH264, "017a000bffe1001c677a000bb6cb41023602d41010110000030001000003003c0f142aa001000568ef0b2c8bfefafa00", ""},
		{"h264/high444/yuv444p", core.CodecH264, "01f4000bffe1001c67f4000b919682046c05a8202022000003000200000300781e28554001000668ef0b112110fff8f800", ""},
		{"h264/high444/yuv444p10le", core.CodecH264, "01f4000bffe1001b67f4000b90d9682046c05a82020220000003002000000781e2855401000668ef0b112110fffafa00", ""},
	} {
		t.Run(fixture.name, func(t *testing.T) {
			// Подтест передаёт настоящую конфигурацию и AU через реальные сериализатор и закреплённую версию SDK.
			// headers и err содержат исходную конфигурацию и ошибку записи hex-эталона.
			headers, err := hex.DecodeString(fixture.headers)
			if err != nil {
				t.Fatal(err)
			}
			// au содержит полный первый независимый AU, не подвергавшийся изменению NAL/OBU.
			au, err := hex.DecodeString(fixture.au)
			if err != nil {
				t.Fatal(err)
			}
			// actual хранит фактическое описание заголовков и независимого кадра.
			var actual core.VideoFormat
			if fixture.videoCodec == core.CodecAV1 {
				actual, _, err = codec.InspectAV1TU(headers, au, core.FrameRate{Numerator: 30, Denominator: 1})
			} else {
				actual, err = codec.H264Format(codec.VideoDescription{Headers: headers, Width: 128, Height: 128})
			}
			if err != nil {
				t.Fatal(err)
			}
			// video содержит реальный поток в шкале миллисекунд общей для исходящего транспорта.
			video, err := media.NewCodecConfig(media.CodecConfigInfo{Track: media.TrackVideo, SourceEpoch: 1, Revision: 1, TimeBase: media.TimeBase{Numerator: 1, Denominator: 1000}, Video: actual}, headers)
			if err != nil {
				t.Fatal(err)
			}
			// audio задаёт обязательную AAC-LC дорожку без изменения принятой схемы ASC/AU.
			_, audio := transportSelfConfigs(t, video.Info().TimeBase)
			// memory и conn проводят исходящие сообщения в изолированную память без внешнего сервера.
			memory := &transportSelfMemory{}
			conn := transportSelfConn(t, memory)
			conn.target.profile = core.MediaFormat{Video: actual, Audio: audio.Info().Audio}
			if err = validateOutboundProfile(conn.target.profile); err != nil {
				t.Fatal(err)
			}
			if err = conn.WriteHeaders(context.Background(), video, audio); err != nil {
				t.Fatal(err)
			}
			// packet сохраняет отрицательное начало; часы исходящего потока должны выбрать общее нулевое начало.
			packet, err := media.NewPacket(media.PacketInfo{DTS: -1, PTS: -1, DurationTicks: 33, Keyframe: false}, video, au)
			if err != nil {
				t.Fatal(err)
			}
			if _, err = conn.WritePacket(context.Background(), packet); err != nil {
				t.Fatal(err)
			}
			// input читает фактически сериализованные исходящие сообщения и их неизменённые тела.
			input := bytes.NewReader(memory.output.Bytes())
			// config и frame содержат исходное сообщение видеоконфигурации и следующее сообщение CodedFrames.
			var config, frame transportSelfFrame
			// index выбирает метаданные, видеоконфигурацию, аудиоконфигурацию и видео AU по штатному порядку.
			for index := range 4 {
				// current содержит очередное полное сообщение исходящего сериализатора;
				// readErr сообщает об отказе чтения его заголовка или тела.
				current, readErr := transportSelfReadFrame(input, 128)
				if readErr != nil {
					t.Fatal(readErr)
				}
				if index == 1 {
					config = current
				}
				if index == 3 {
					frame = current
				}
			}
			if !bytes.Equal(config.body[5:], headers) || !bytes.Equal(frame.body[5:], au) || frame.stamp != 0 {
				t.Fatal("Native RTMP изменил config/AU/time")
			}
			if fixture.videoCodec == core.CodecAV1 {
				// wire использует те же исходные байты VideoExSequenceStart на ограниченном пути приёма.
				wire := guarded(t, chunk0(6, 9, config.body), testLimits())
				// counter и sdk сохраняют единственный реальный читатель SDK без переупаковки av1C.
				// Его обработчик подтверждает ACK без ввода-вывода в тесте одного сообщения.
				counter := bytecounter.NewReader(wire)
				sdk := message.NewReader(counter, counter, func(uint32) error { return nil })
				// decoded и readErr содержат реальный результат разбора VideoExSequenceStart для AV1.
				decoded, readErr := wire.readMessage(sdk.Read)
				if readErr != nil {
					t.Fatal(readErr)
				}
				// start и ok проверяют описание SDK вместо доверия одному типу исходного сообщения.
				start, ok := decoded.(*message.VideoExSequenceStart)
				if !ok || start.AV1Config == nil || start.AV1Config.SeqProfile != headers[1]>>5 || start.AV1Config.HighBitdepth != (headers[2]>>6)&1 || start.AV1Config.Monochrome != (headers[2]>>4)&1 || start.AV1Config.ChromaSubsamplingX != (headers[2]>>3)&1 || start.AV1Config.ChromaSubsamplingY != (headers[2]>>2)&1 || !bytes.Equal(wire.lastConfig[5:], headers) {
					t.Fatalf("Неверный SDK descriptor: %+v", decoded)
				}
			}
			// mismatch объявляет ложный level, который пустое ограничение назначения не проверяет.
			mismatch := video.Info()
			mismatch.Video.Level = "6.0"
			conn.target.profile.Video.Level = ""
			video, err = media.NewCodecConfig(mismatch, headers)
			if err != nil {
				t.Fatal(err)
			}
			// before сохраняет объём уже отправленных данных: ложная конфигурация должна
			// отвергаться по фактическим заголовкам до новой записи и ожидания первого AU.
			before := memory.output.Len()
			if err = conn.WriteHeaders(context.Background(), video, audio); err == nil || memory.output.Len() != before {
				t.Fatal("Принят ложный level при пустом ограничении назначения", err)
			}
		})
	}
}
